`meta.json` holds the token ids and lengths per text. Next I'll rebuild the same 250 texts locally, confirm their tokenization matches the tool's, and check the topk/logprob alignment convention on one text.

<python>
# Hypothesis: tool tokenization == local tokenization; topk at t predicts t+1.
conds=['NG','P0','P1','P3','P5']
PHt={'P0':PH['P0'],'P1':PH['P1'],'P3':PH['P3'],'P5':PH['P5']}
def mk(f,cond,ans):
    u = f['question'] if cond=='NG' else PH[cond].format(q=f['question'],g=f['guess'])
    return chat_text(u, reply(ans))
T1=[]; M1=[]
for cond in conds:
    for f in facts:
        ans = f['correct'] if cond=='NG' else f['guess']
        T1.append(mk(f,cond,ans)); M1.append((f['id'],cond))
mt=F1['meta']['tokens']; 
mism=[i for i,t in enumerate(T1) if tok.encode(t,add_special_tokens=False).ids!=mt[i]]
print('mismatch', len(mism), mism[:5])
i=0; L=F1['meta']['lengths'][i]; ids=mt[i]
tl=F1['token_logprobs'][i]; ti=F1['topk_ids'][i]; tlp=F1['topk_logprobs'][i]
for t in range(L-6,L):
    j=np.where(ti[t-1]==ids[t])[0]
    print(t, ids[t], round(float(tl[t]),3), (round(float(tlp[t-1][j[0]]),3) if len(j) else None))
