# Is the P0 'defer' signal an add-on (NG~0) at reader inputs? projections onto paired P0-NG mean diff in normed space (pass 1 hidden)
def normed(h, L):
    w = load(f'model.layers.{L}.input_layernorm.weight').numpy()
    return h / np.sqrt((h**2).mean(-1, keepdims=True) + 1e-6) * (1 + w)
DP = {}
for c in conds1:
    DP[c] = [dec_pos(tk1[conds1.index(c)*50+fid], devF[fid]) for fid in range(50)]
HN = {}
for L in [3,5,6,7,9,10,12]:
    Hs = np.load(f'/work/fwd_1/hidden_{L}.npy', mmap_mode='r')
    for c in conds1:
        rows = np.stack([np.asarray(Hs[conds1.index(c)*50+fid, DP[c][fid]]) for fid in range(50)])
        HN[(L,c)] = normed(rows.astype(np.float64), L)
    d = (HN[(L,'P0')] - HN[(L,'NG')]); u = d.mean(0); u /= np.linalg.norm(u)
    pr = {c: HN[(L,c)] @ u for c in conds1}
    # LOFO-free summary: mean and sd of projection per cond; also fraction of P0-NG diff energy captured by u
    frac = ((d@u)**2).sum() / (d**2).sum()
    print(f"L{L}: " + " ".join(f"{c} {pr[c].mean():+.1f}±{pr[c].std():.1f}" for c in conds1) + f" | |n(h)| {np.linalg.norm(HN[(L,'NG')],axis=1).mean():.0f} | rank1 frac of diff {frac:.2f}")
